import React, { useMemo } from 'react';
import { ResponsiveContainer, ComposedChart, Line, XAxis, YAxis, CartesianGrid, Tooltip } from 'recharts';
import { Transaction, Account, Goal, Budget, UserPlan, SpendingStatus, SpendingPeriod, TransactionType } from '../types';
import { Wallet, CreditCard, Activity, ArrowUpRight, ArrowDownRight, Zap, Plus, Eye, EyeOff } from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string, params?: any) => void;
  onAddTransaction: () => void;
  onAddGoal: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan: UserPlan;
  onAskCoach: (query: string) => void;
  insightUsage: number;
  spendingStatus: SpendingStatus;
  currentPeriodSpend: number;
  spendingLimit: number;
  spendingPeriod: SpendingPeriod;
  userName: string;
  isPrivacyMode: boolean;
  onTogglePrivacy: () => void;
  creditScore: number;
}

const CustomChartTooltip = ({ active, payload, label, formatCurrency }: any) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-[#0f172a] border border-white/10 p-4 rounded-2xl shadow-xl backdrop-blur-md">
        <p className="text-slate-400 text-xs font-bold uppercase mb-2">{label}</p>
        {payload.map((entry: any, index: number) => (
          <div key={index} className="flex items-center gap-2 text-sm mb-1">
            <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.stroke || entry.fill }}></div>
            <span className="font-medium text-white">
              {entry.name}: {formatCurrency(entry.value)}
            </span>
          </div>
        ))}
      </div>
    );
  }
  return null;
};

const Dashboard: React.FC<DashboardProps> = ({
  accounts,
  transactions,
  onNavigate,
  onAddTransaction,
  formatCurrency,
  spendingStatus,
  currentPeriodSpend,
  spendingPeriod,
  userName,
  isPrivacyMode,
  onTogglePrivacy,
  creditScore
}) => {
  // Logic for Net Worth
  const netWorth = accounts.reduce((sum, acc) => sum + acc.balance, 0);

  // Logic for Line Chart Data (Spend Trajectory)
  const lineChartData = useMemo(() => {
    const today = new Date();
    const daysInMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate();
    const currentMonthData = new Array(daysInMonth).fill(0);
    const prevMonthData = new Array(daysInMonth).fill(0);

    transactions.forEach(t => {
      const d = new Date(t.date);
      if (t.type === TransactionType.EXPENSE) {
        if (d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear()) {
          currentMonthData[d.getDate() - 1] += t.amount;
        } else if (d.getMonth() === today.getMonth() - 1 || (today.getMonth() === 0 && d.getMonth() === 11 && d.getFullYear() === today.getFullYear() - 1)) {
          prevMonthData[d.getDate() - 1] += t.amount;
        }
      }
    });

    // Cumulative sum
    let currentSum = 0;
    let prevSum = 0;
    const data = [];
    for (let i = 0; i < daysInMonth; i++) {
      currentSum += currentMonthData[i];
      prevSum += prevMonthData[i];
      // Only push current data up to today
      const isFuture = i >= today.getDate();

      data.push({
        day: i + 1,
        ThisMonth: isFuture ? null : currentSum,
        Comparison: prevSum
      });
    }
    return data;
  }, [transactions]);

  // Logic for Recent Transactions (Top 3)
  const recentTransactions = transactions.slice(0, 3);

  return (
    <div className="space-y-8 animate-slide-up pb-10">
      {/* Header with Greeting & Quick Actions */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-white tracking-tight flex items-center gap-2">
            Hello, {userName} <span className="text-2xl">👋</span>
          </h2>
          <p className="text-slate-400 font-medium mt-1">Financial system operational.</p>
        </div>
        <div className="flex items-center gap-3">
           <button 
             onClick={onTogglePrivacy}
             className="p-3 bg-slate-900 border border-white/10 rounded-xl text-slate-400 hover:text-white transition-colors"
           >
             {isPrivacyMode ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
           </button>
           <button 
             onClick={onAddTransaction}
             className="flex items-center gap-2 px-5 py-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-bold shadow-lg shadow-indigo-500/20 active:scale-95 transition-all"
           >
             <Plus className="w-5 h-5" />
             <span className="hidden md:inline">Log Event</span>
           </button>
        </div>
      </div>

      {/* Main Metrics Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">

        {/* Net Worth Card */}
        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-[#0f172a] relative overflow-hidden group">
           <div className="absolute top-0 right-0 p-6 opacity-10 group-hover:opacity-20 transition-opacity">
             <Wallet className="w-16 h-16 text-indigo-500" />
           </div>
           <div className="relative z-10">
             <p className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-1">Net Worth</p>
             <h3 className="text-3xl font-black text-white tracking-tight mb-4">{formatCurrency(netWorth)}</h3>
             <div className="flex items-center gap-2">
                <span className="text-xs font-bold text-emerald-400 bg-emerald-500/10 px-2 py-1 rounded-lg border border-emerald-500/20">+4.2%</span>
                <span className="text-xs text-slate-500 font-medium">vs last month</span>
             </div>
           </div>
        </div>

        {/* Monthly Spend Card */}
        <div className={`glass-card p-6 rounded-[2rem] border relative overflow-hidden group transition-all ${spendingStatus.colorClass}`}>
           <div className="absolute top-0 right-0 p-6 opacity-10 group-hover:opacity-20 transition-opacity">
             <CreditCard className="w-16 h-16 text-current" />
           </div>
           <div className="relative z-10">
             <p className="text-sm font-bold text-current opacity-80 uppercase tracking-widest mb-1">{spendingPeriod === 'monthly' ? 'Monthly' : 'Weekly'} Spend</p>
             <h3 className="text-3xl font-black text-white tracking-tight mb-4">{formatCurrency(currentPeriodSpend)}</h3>
             <div className="flex items-center gap-2">
                <span className={`text-xs font-bold px-2 py-1 rounded-lg border border-current opacity-80`}>
                  {spendingStatus.message}
                </span>
             </div>
             {/* Progress Bar */}
             <div className="mt-4 w-full h-1.5 bg-black/20 rounded-full overflow-hidden">
                <div className="h-full bg-current" style={{ width: `${Math.min(spendingStatus.ratio * 100, 100)}%` }}></div>
             </div>
           </div>
        </div>

        {/* Credit Score / Health Card */}
        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-[#0f172a] relative overflow-hidden group">
           <div className="absolute top-0 right-0 p-6 opacity-10 group-hover:opacity-20 transition-opacity">
             <Activity className="w-16 h-16 text-purple-500" />
           </div>
           <div className="relative z-10">
             <p className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-1">Financial Health</p>
             <h3 className="text-3xl font-black text-white tracking-tight mb-4">{creditScore > 0 ? creditScore : '---'}</h3>
             <div className="flex items-center gap-2">
                <span className={`text-xs font-bold px-2 py-1 rounded-lg border ${creditScore >= 720 ? 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20' : creditScore >= 650 ? 'text-amber-400 bg-amber-500/10 border-amber-500/20' : 'text-slate-400 bg-slate-500/10 border-slate-500/20'}`}>
                   {creditScore >= 750 ? 'Excellent' : creditScore >= 700 ? 'Good' : creditScore > 0 ? 'Fair' : 'Calibrate in Settings'}
                </span>
             </div>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {/* Spend Trajectory Chart (2/3 width) */}
          <div className="md:col-span-2 glass-card p-6 md:p-8 rounded-[2.5rem] border border-white/5 bg-[#0f172a] flex flex-col relative overflow-hidden h-[25rem]">
              {/* Header & Legend */}
              <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 relative z-10">
                  <div>
                      <h3 className="text-xl font-bold text-white tracking-tight">Spend Trajectory</h3>
                      <p className="text-sm text-slate-400 font-medium mt-1">Cumulative spending vs previous month</p>
                  </div>
                  <div className="flex items-center gap-6 mt-4 md:mt-0">
                        <div className="flex items-center gap-2">
                          <div className="w-2.5 h-2.5 rounded-full bg-[#6366f1] shadow-[0_0_8px_#6366f1]"></div>
                          <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">Current</span>
                      </div>
                      <div className="flex items-center gap-2">
                          <div className="w-2.5 h-2.5 rounded-full bg-slate-600"></div>
                          <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Previous</span>
                      </div>
                  </div>
              </div>

              {/* Chart Area */}
              <div className="flex-1 w-full min-h-0 relative z-10">
                  <ResponsiveContainer width="100%" height="100%">
                      <ComposedChart data={lineChartData} margin={{ top: 20, right: 40, left: 20, bottom: 40 }}>
                          <defs>
                              <linearGradient id="colorThisMonth" x1="0" y1="0" x2="0" y2="1">
                                  <stop offset="5%" stopColor="#6366f1" stopOpacity={0.5}/>
                                  <stop offset="95%" stopColor="#6366f1" stopOpacity={0.05}/>
                              </linearGradient>
                          </defs>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="rgba(255,255,255,0.05)" />
                          <XAxis 
                              dataKey="day" 
                              stroke="#475569" 
                              fontSize={11} 
                              tickLine={false} 
                              axisLine={false} 
                              dy={10}
                              tick={{ fill: '#64748b', fontWeight: '500' }}
                              interval="preserveStartEnd"
                          />
                          <YAxis 
                              stroke="#475569" 
                              fontSize={11} 
                              tickLine={false} 
                              axisLine={false} 
                              tickFormatter={(val) => isPrivacyMode ? '•••' : `$${val}`}
                              tickCount={6}
                              width={40}
                              tick={{ fill: '#64748b', fontWeight: '500' }}
                          />
                          <Tooltip content={<CustomChartTooltip formatCurrency={formatCurrency} />} cursor={{ stroke: 'rgba(255,255,255,0.1)', strokeWidth: 1 }} />

                          {/* Previous Period Line */}
                          <Line 
                              type="monotone" 
                              dataKey="Comparison" 
                              stroke="#475569" 
                              strokeWidth={2} 
                              dot={false} 
                              strokeDasharray="4 4" 
                              activeDot={false}
                          />
                          {/* Current Period Line */}
                          <Line 
                              type="monotone" 
                              dataKey="ThisMonth" 
                              stroke="#6366f1" 
                              strokeWidth={3} 
                              dot={false}
                              activeDot={{ r: 6, strokeWidth: 0, fill: '#6366f1' }}
                          />
                      </ComposedChart>
                  </ResponsiveContainer>
              </div>
          </div>

          {/* Quick Actions / Recent Activity (1/3 width) */}
          <div className="flex flex-col gap-6">
             {/* AI Insight Teaser */}
             <div 
               onClick={() => onNavigate('insights', { reportType: 'daily' })}
               className="glass-card p-6 rounded-[2.5rem] border border-indigo-500/20 bg-indigo-500/5 hover:bg-indigo-500/10 cursor-pointer transition-all group relative overflow-hidden"
             >
                <div className="flex justify-between items-start mb-4">
                   <div className="p-3 bg-indigo-500/20 rounded-xl text-indigo-400">
                      <Zap className="w-6 h-6" />
                   </div>
                   <ArrowUpRight className="w-5 h-5 text-slate-500 group-hover:text-white transition-colors" />
                </div>
                <h4 className="text-lg font-bold text-white mb-1">Daily Brief</h4>
                <p className="text-xs text-slate-400 font-medium leading-relaxed">
                   Check today's financial pulse. {spendingStatus.status === 'violation' ? 'Critical alert active.' : 'Status nominal.'}
                </p>
             </div>

             {/* Recent Transactions List */}
             <div className="flex-1 glass-card p-6 rounded-[2.5rem] border border-white/5 bg-[#0f172a] overflow-hidden flex flex-col">
                <div className="flex justify-between items-center mb-4">
                   <h4 className="font-bold text-white text-sm uppercase tracking-wider">Recent Activity</h4>
                   <button onClick={() => onNavigate('transactions')} className="text-[10px] font-bold text-indigo-400 hover:text-indigo-300 uppercase tracking-widest">View All</button>
