                <div className="flex-1 overflow-y-auto custom-scrollbar space-y-3 pr-2">
                   {recentTransactions.length === 0 ? (
                      <div className="text-center text-slate-500 text-xs py-8">No recent activity</div>
                   ) : (
                      recentTransactions.map(t => (
                        <div key={t.id} className="flex justify-between items-center p-3 hover:bg-white/5 rounded-xl transition-colors group">
                           <div className="flex items-center gap-3">
                              <div className={`p-2 rounded-full ${t.type === TransactionType.EXPENSE ? 'bg-rose-500/10 text-rose-400' : 'bg-emerald-500/10 text-emerald-400'}`}>
