                              </div>
                           </div>
                           <span className={`text-sm font-bold ${t.type === TransactionType.EXPENSE ? 'text-white' : 'text-emerald-400'}`}>
                              {t.type === TransactionType.EXPENSE ? '-' : '+'}{formatCurrency(t.amount)}
                           </span>
                        </div>
                      ))
                   )}
                </div>
             </div>
          </div>
      </div>
    </div>
  );
};

export default Dashboard;
